 function homeworkUpdatesInput_(){
 const A=root.TrialHomeworkArchive,records=[];
 const reference=Number(lastInput.serverNow)||lastInput.profile.kidsJourneyV1.sourceAt;
 // This is notification metadata from the canonical result, never a receipt verdict.
 const receiptNotice=t=>{
  if(t.complete!==true||!t.submittedAt)return null;
  const d=root.TrialKidsJourneyParser.date(t.submittedAt),time=String(t.submittedAt).match(/\b(\d{1,2}):(\d{2})(?::\d{2})?\b/);
  if(!d||!time||+time[1]>23||+time[2]>59)return null;
  return {at:d.at+(+time[1]*60+ +time[2])*60000,count:Number.isFinite(t.attempts)?t.attempts:0,label:t.submittedAt};
 };
 for(const s of model.sessions.filter(s=>!s.future)){
  const a=homeworkDemoNative_(s),label='Tiết '+s.number+' · '+A.name(a?.program||s.program)+' · '+s.date;
  if(!a&&!s.tasks.length&&!s.paper?.grade&&!s.teacherNote&&!Number.isFinite(s.stars))continue;
  records.push({id:'session:'+s.id,kind:a?'course':'result',detailId:s.id,label,signals:{paper:s.paper?.grade,stars:Number.isFinite(s.stars)?s.stars:null,comment:[s.teacherNote,s.assignmentNote].filter(Boolean).join('\n')}});
  for(const t of s.tasks)records.push({id:'task:'+s.id+':'+t.id,kind:'result',detailId:s.id,label:t.title+' · '+label,receipt:receiptNotice(t),signals:{score:Number.isFinite(t.percentage)?t.percentage:null,mark:Number.isFinite(t.score)&&Number.isFinite(t.maximum)&&t.maximum>0?t.score+'/'+t.maximum:null,comment:t.comment}});
 }
 for(const v of model.videos){
  const rows=(lastInput.practice||[]).filter(r=>r.id===v.nativeAssignmentId);
  // The native released row is the authority. isNew is an optional visual hint,
  // not a prerequisite for announcing a genuinely current Schedule release.
  const releasedAt=rows.length===1?root.TrialKidsJourneyParser.date(rows[0].assignedDate||rows[0].lessonDate||rows[0].date)?.at:null;
  const currentRelease=Number.isFinite(releasedAt)&&reference>=releasedAt&&reference-releasedAt<=3*86400000;
  records.push({id:'video:'+v.id,aliases:v.components?.length===1?['practice-component:'+v.id+':'+v.components[0].id]:[],kind:rows.length===1?'practice':'result',detailId:v.id,label:'Video tự luyện ('+A.name(v.program)+') · Bài '+v.number,explicitNew:currentRelease,complete:v.complete,receipt:v.components?.length>1?null:receiptNotice(v),signals:v.components?.length>1?{}:{score:Number.isFinite(v.percentage)?v.percentage:null,comment:v.comment}});
 }
 // Preferences belong to the already verified parent route, not mutable name casing.
 // This is only a browser preference namespace; it never grants profile access.
 for(const v of model.videos)for(const t of (v.components?.length>1?v.components:[]))records.push({
   id:'practice-component:'+v.id+':'+t.id,kind:'result',detailId:v.id,label:t.title+' · '+v.program+' · Bài '+v.number,
   receipt:receiptNotice(t),signals:{score:Number.isFinite(t.percentage)?t.percentage:null,
    mark:Number.isFinite(t.score)&&t.maximum>0?t.score+'/'+t.maximum:null,comment:t.comment}});
 const legacyStudentKey=model.className+'|'+model.fullName+'|'+model.alias;
 const parentRoute=typeof location!=='undefined'?location.hash:'';
 return {studentKey:parentRoute?model.className+'|'+parentRoute:legacyStudentKey,legacyStudentKey,now:reference,records};
}

